/**
 * Buffers genuinely cold Sail rows before SailRepositoryConnection can prepare their values. Writers delete the
 * referenced terms and components while readers hold them, and reuse IDs from an older, already released cohort.
 */
class LmdbBufferedTripleTermTest {

	private static final ValueFactory VF = SimpleValueFactory.getInstance();
	private static final int DEPTH = 6;
	private static final int ROWS = 8;
	private static final int SHARED_ROWS = 4;
	private static final int WRITERS = 4;
	private static final int ROUNDS = 6;
	private static final IRI PREDICATE = VF.createIRI("urn:buffered-terms:statement-predicate");
	private static final IRI OLD_CONTEXT = context("released");
	private static final IRI SHARED_OWNER_CONTEXT = context("remaining-shared-owner");
	private static final IRI[] CONTEXTS = { context("a"), context("b"), context("c"), context("d") };

	private enum Route {
		STATEMENTS,
		TUPLE_QUERY
	}

	private enum SourceLifetime {
		OPEN,
		EXHAUSTED_AND_CLOSED
	}

	private enum ReaderTransaction {
		IMPLICIT(null),
		READ_COMMITTED(IsolationLevels.READ_COMMITTED),
		SNAPSHOT_READ(IsolationLevels.SNAPSHOT_READ),
		SNAPSHOT(IsolationLevels.SNAPSHOT),
		SERIALIZABLE(IsolationLevels.SERIALIZABLE);

		private final IsolationLevels isolation;

		ReaderTransaction(IsolationLevels isolation) {
			this.isolation = isolation;
		}
	}

	static Stream<Arguments> transactionCases() {
		return Stream.of(Route.values())
				.flatMap(route -> Stream.of(SourceLifetime.values())
						.flatMap(lifetime -> Stream.of(ReaderTransaction.values())
								.map(transaction -> Arguments.of(route, lifetime, transaction))));
	}

	@ParameterizedTest(name = "{0}, source={1}, reader={2}")
	@MethodSource("transactionCases")
	void unresolvedBuffersSurviveOverlappingRemovalAndRealIdReuse(Route route, SourceLifetime lifetime,
			ReaderTransaction transaction, @TempDir File directory) throws Exception {
		Seed seed = seed(directory);
		LmdbStore store = newStore(directory);
		BufferingSail buffering = new BufferingSail(store);
		SailRepository repository = new SailRepository(buffering);
		repository.init();
		// Reopening releases the old cohort before any new reader owns its dictionary epoch.
		long initialFree = entries(store, "free_ids");
		assertTrue(initialFree > 0, "The released cohort must supply physically reclaimable IDs");
		int[][] selections = { { 0 }, { 0 }, { 1 }, { 1, 2 }, { 2, 3 }, { 3 } };
		CountDownLatch buffered = new CountDownLatch(selections.length);
		CountDownLatch releaseReaders = new CountDownLatch(1);
		CountDownLatch writersBegun = new CountDownLatch(WRITERS);
		CountDownLatch releaseWriters = new CountDownLatch(1);
		CountDownLatch firstOwnersDeleted = new CountDownLatch(2);
		CountDownLatch releaseRemainingOwners = new CountDownLatch(1);
		List<BufferGate> gates = new ArrayList<>();
		List<Future<List<Statement>>> readers = new ArrayList<>();
		List<Future<?>> writers = new ArrayList<>();
		ReuseEvidence reuse = new ReuseEvidence(initialFree);
		AtomicInteger commits = new AtomicInteger();
		try (ExecutorService workers = Executors.newFixedThreadPool(selections.length + WRITERS)) {
			try {
				for (int[] selection : selections) {
					BufferGate gate = new BufferGate(selection.length * (ROWS + SHARED_ROWS), lifetime, buffered,
							releaseReaders);
					gates.add(gate);
					readers.add(workers.submit(() -> read(repository, buffering, gate, route, transaction, selection)));
				}
				await(buffered, "all independent reader connections must buffer before writers start");
				for (BufferGate gate : gates) {
					assertEquals(null, gate.failure, "Reader fixture failed before reaching its holding barrier");
					gate.assertUnresolved();
				}
				for (int writer = 0; writer < WRITERS; writer++) {
					int index = writer;
					writers.add(workers.submit(() -> {
						write(repository, store, index, writersBegun, releaseWriters, firstOwnersDeleted,
								releaseRemainingOwners, reuse, commits);
						return null;
					}));
				}
				await(writersBegun, "independent writer transactions must begin together while readers are held");
				releaseWriters.countDown();
				await(firstOwnersDeleted,
						"both completely overlapping writers must commit removal of the first owners");
				// An independent outer owner lets us read the shared children without initializing any buffered
				// outer root. C/D also retain their original rows until the remaining writers are released.
				try (RepositoryConnection remaining = repository.getConnection();
						RepositoryResult<Statement> result = remaining.getStatements(null, null, null, false,
								SHARED_OWNER_CONTEXT)) {
					assertStatements(seed.sharedOwners, result.stream().toList());
					assertEquals(0, remaining.size(CONTEXTS[0], CONTEXTS[1]));
					assertEquals(2 * (ROWS + SHARED_ROWS), remaining.size(CONTEXTS[2], CONTEXTS[3]));
				}
				gates.forEach(BufferGate::assertUnresolved);
				releaseRemainingOwners.countDown();
				for (Future<?> writer : writers) {
					writer.get(30, TimeUnit.SECONDS);
				}
				// Remove the final shared owner only after the intermediate shared-component verification.
				try (RepositoryConnection lastOwner = repository.getConnection()) {
					lastOwner.begin(IsolationLevels.READ_COMMITTED);
					lastOwner.clear(SHARED_OWNER_CONTEXT);
					lastOwner.commit();
					commits.incrementAndGet();
					assertEquals(0, lastOwner.size(SHARED_OWNER_CONTEXT));
				}
				assertEquals(WRITERS * (1 + 2 * ROUNDS) + 1, commits.get(),
						"All delete/add/remove transactions must commit");
				try (RepositoryConnection check = repository.getConnection()) {
					for (IRI context : CONTEXTS) {
						assertEquals(0, check.size(context),
								"Original and replacement statements must actually be gone");
					}
				}
				for (BufferGate gate : gates) {
					gate.assertUnresolved();
					assertEquals(lifetime == SourceLifetime.EXHAUSTED_AND_CLOSED, gate.sourceClosed);
				}
				// Source/transaction owners can still reference logically deleted dictionaries. Successful commits
				// and fresh repository reads prove deletion; ID intersections separately prove physical recycling.
				long heldUnused = entries(store, "unused_ids");
				assertTrue(reuse.minimumFree.get() < initialFree, "Writers must consume the old physical free-ID pool");
				assertTrue(intersects(seed.releasedIds, reuse.componentIds),
						"A replacement component must reuse an old ID");
				assertTrue(intersects(seed.releasedTripleIds, reuse.tripleIds),
						"A replacement triple term must reuse an old ID");
				releaseReaders.countDown();
				List<List<Statement>> retained = new ArrayList<>();
				for (int reader = 0; reader < readers.size(); reader++) {
					List<Statement> actual = readers.get(reader).get(30, TimeUnit.SECONDS);
					assertStatements(expected(seed.statements, selections[reader]), actual);
					retained.add(actual);
				}
				for (BufferGate gate : gates) {
					assertTrue(gate.sourceClosed, "Closing the outward result must close its buffered source");
				}
				repository.shutDown();
				for (int reader = 0; reader < retained.size(); reader++) {
					assertStatements(expected(seed.statements, selections[reader]), retained.get(reader));
				}
				System.out.printf(
						"buffered-terms route=%s source=%s reader=%s readers=%d commits=%d heldUnused=%d free=%d->%d reusedComponents=%d reusedTriples=%d%n",
						route, lifetime, transaction, selections.length, commits.get(), heldUnused, initialFree,
						reuse.minimumFree.get(),
						intersectionSize(seed.releasedIds, reuse.componentIds),
						intersectionSize(seed.releasedTripleIds, reuse.tripleIds));
			} finally {
				releaseReaders.countDown();
				releaseWriters.countDown();
				releaseRemainingOwners.countDown();
				readers.forEach(future -> future.cancel(true));
				writers.forEach(future -> future.cancel(true));
			}
		} finally {
			repository.shutDown();
		}
	}

	@Test
	void escapedNestedChildRemainsLazyAcrossParentAndTransactionClosure(@TempDir File directory) throws Exception {
		Seed seed = seed(directory);
		LmdbStore store = newStore(directory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		Value child;
		Value expectedChild = ((TripleTerm) seed.statements.get(0).getObject()).getObject();
		try {
			try (NotifyingSailConnection reader = store.getConnection()) {
				reader.begin(IsolationLevels.SNAPSHOT_READ);
				try (CloseableIteration<? extends Statement> source = reader.getStatements(
						seed.statements.get(0).getSubject(), null, null, false, CONTEXTS[0])) {
					assertTrue(source.hasNext());
					LmdbValue parent = assertUnresolved(source.next().getObject());
					child = ((TripleTerm) parent).getObject();
					assertUnresolved(child);
					assertFalse(source.hasNext());
				}
				reader.rollback();
			}
			for (int round = 0; round < ROUNDS; round++) {
				try (RepositoryConnection writer = repository.getConnection()) {
					writer.begin(IsolationLevels.READ_COMMITTED);
					writer.clear(CONTEXTS);
					addRows(writer, "escaped-churn-" + round, ROWS, CONTEXTS[0]);
					writer.commit();
				}
				assertUnresolved(child);
			}
			// Decode one layer at a time, keeping each newly escaped descendant cold across another commit.
			while (expectedChild instanceof TripleTerm expectedTerm) {
				TripleTerm term = assertInstanceOf(TripleTerm.class, child);
				assertCompleteValue(expectedTerm.getSubject(), term.getSubject());
				assertCompleteValue(expectedTerm.getPredicate(), term.getPredicate());
				child = term.getObject();
				expectedChild = expectedTerm.getObject();
				assertUnresolved(child);
				try (RepositoryConnection writer = repository.getConnection()) {
					writer.begin(IsolationLevels.READ_COMMITTED);
					writer.clear(CONTEXTS);
					writer.commit();
				}
				assertUnresolved(child);
			}
			assertCompleteValue(expectedChild, child);
			repository.shutDown();
			assertCompleteValue(expectedChild, child);
		} finally {
			repository.shutDown();
		}
	}

	@ParameterizedTest(name = "structural cycle length={0}")
	@ValueSource(ints = { 1, 2 })
	void characterizeCyclicCallerModelsInIsolatedProcess(int cycleLength, @TempDir Path directory) throws Exception {
		Path output = directory.resolve("cycle-process.log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-Xss512k", "-Xmx256m", "-cp", System.getProperty("java.class.path"), CycleProbe.class.getName(),
				directory.resolve("store").toString(), Integer.toString(cycleLength))
						.redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(process.waitFor(30, TimeUnit.SECONDS),
					"Malformed cyclic input must terminate in the isolated process");
			String result = Files.readString(output, StandardCharsets.UTF_8);
			System.out.print(result);
			assertEquals(0, process.exitValue(), result);
			assertTrue(result.contains("CYCLE_OUTCOME=REJECTED class=java.lang.IllegalArgumentException"),
					"Cyclic values must be rejected cleanly before model hashing or persistence: " + result);
			assertTrue(result.contains("VALID_RECOVERY=true"),
					"The store must still accept and return valid nested terms: " + result);
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
				assertTrue(process.waitFor(5, TimeUnit.SECONDS), "The isolated malformed-input probe must terminate");
			}
		}
	}

	/**
	 * Runs malformed caller implementations separately so regressions to unbounded traversal cannot damage the
	 * repository-recovery probe.
	 */
	public static final class CycleProbe {
		public static void main(String[] args) {
			SailRepository repository = new SailRepository(newStore(new File(args[0])));
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				CyclicTerm first = new CyclicTerm("first");
				CyclicTerm second = Integer.parseInt(args[1]) == 1 ? first : new CyclicTerm("second");
				first.object = second;
				second.object = first;
				assertTrue(first.getObject() == second && second.getObject() == first,
						"This must be an actual structural object cycle, not an ordinary RDF graph cycle");
				connection.begin(IsolationLevels.READ_COMMITTED);
				try {
					connection.add(VF.createIRI("urn:cycle:subject"), PREDICATE, first);
					connection.commit();
					System.out.println("CYCLE_OUTCOME=ACCEPTED");
				} catch (StackOverflowError failure) {
					System.out.println("CYCLE_OUTCOME=STACK_OVERFLOW");
					printCycleFailure(failure);
				} catch (RuntimeException failure) {
					System.out.println("CYCLE_OUTCOME=REJECTED class=" + failure.getClass().getName());
					printCycleFailure(failure);
				} finally {
					if (connection.isActive()) {
						connection.rollback();
					}
				}
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.clear();
				List<Statement> valid = addRows(connection, "cycle-recovery", 4, CONTEXTS[0]);
				// An ordinary RDF graph cycle is valid and independent of nested object structure.
				IRI a = VF.createIRI("urn:graph-cycle:a");
				IRI b = VF.createIRI("urn:graph-cycle:b");
				Statement ab = VF.createStatement(a, PREDICATE, b, CONTEXTS[1]);
				Statement ba = VF.createStatement(b, PREDICATE, a, CONTEXTS[1]);
				connection.add(ab);
				connection.add(ba);
				valid.add(ab);
				valid.add(ba);
				connection.commit();
				try (RepositoryResult<Statement> rows = connection.getStatements(null, null, null, false)) {
					assertStatements(valid, rows.stream().toList());
				}
				System.out.println("VALID_RECOVERY=true");
			} finally {
				repository.shutDown();
			}
		}

		private static void printCycleFailure(Throwable failure) {
			String message = failure.getMessage();
			System.out.println("CYCLE_FAILURE=" + failure.getClass().getName() + " message="
					+ (message == null ? "null" : message.substring(0, Math.min(256, message.length()))));
			Arrays.stream(failure.getStackTrace())
					.limit(8)
					.forEach(frame -> System.out.println("CYCLE_FRAME=" + frame));
		}
	}

	private static final class CyclicTerm extends AbstractTripleTerm {
		private static final long serialVersionUID = 1L;
		private final IRI subject;
		private Value object;

		private CyclicTerm(String name) {
			subject = VF.createIRI("urn:structural-cycle:" + name);
		}

		@Override
		public Resource getSubject() {
			return subject;
		}

		@Override
		public IRI getPredicate() {
			return PREDICATE;
		}

		@Override
		public Value getObject() {
			return object;
		}
	}

	private static List<Statement> read(SailRepository repository, BufferingSail buffering, BufferGate gate,
			Route route,
			ReaderTransaction transaction, int[] selection) {
		List<Statement> statements = new ArrayList<>();
		buffering.gate.set(gate);
		try (RepositoryConnection reader = repository.getConnection()) {
			if (transaction.isolation != null) {
				reader.begin(transaction.isolation);
			}
			Resource[] contexts = Arrays.stream(selection)
					.mapToObj(index -> CONTEXTS[index])
					.toArray(Resource[]::new);
			if (route == Route.STATEMENTS) {
				try (RepositoryResult<Statement> result = reader.getStatements(null, null, null, false, contexts)) {
					while (result.hasNext()) {
						Statement statement = result.next();
						assertReady(statement.getObject());
						statements.add(statement);
					}
				}
			} else {
				String values = Stream.of(contexts)
						.map(context -> "<" + context.stringValue() + ">")
						.reduce((left, right) -> left + ", " + right)
						.orElseThrow();
				String query = "SELECT ?s ?p ?o ?g WHERE { GRAPH ?g { ?s ?p ?o } FILTER (?g IN (" + values + ")) }";
				try (TupleQueryResult result = reader.prepareTupleQuery(query).evaluate()) {
					while (result.hasNext()) {
						BindingSet row = result.next();
						assertReady(row.getValue("o"));
						statements.add(VF.createStatement((Resource) row.getValue("s"), (IRI) row.getValue("p"),
								row.getValue("o"), (Resource) row.getValue("g")));
					}
				}
			}
			if (reader.isActive()) {
				reader.rollback();
			}
			return statements;
		} finally {
			buffering.gate.remove();
		}
	}

	private static void write(SailRepository repository, LmdbStore store, int writer, CountDownLatch begun,
			CountDownLatch release, CountDownLatch firstOwnersDeleted, CountDownLatch releaseRemainingOwners,
			ReuseEvidence reuse, AtomicInteger commits) {
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			begun.countDown();
			await(release, "writer transactions must overlap before their first mutation");
			Resource[] assigned = switch (writer) {
			case 0, 1 -> new Resource[] { CONTEXTS[0], CONTEXTS[1] };
			case 2 -> new Resource[] { CONTEXTS[1], CONTEXTS[2] };
			default -> new Resource[] { CONTEXTS[3] };
			};
			if (writer >= 2) {
				await(releaseRemainingOwners, "the still-referenced shared components must be checked first");
			}
			connection.clear(assigned);
			connection.commit();
			commits.incrementAndGet();
			if (writer < 2) {
				firstOwnersDeleted.countDown();
				await(releaseRemainingOwners, "the remaining shared owners must be checked before replacement churn");
			}
			for (int round = 0; round < ROUNDS; round++) {
				connection.begin(IsolationLevels.READ_COMMITTED);
				for (Resource context : assigned) {
					String prefix = "writer-" + writer + "-round-" + round + "-" + ((IRI) context).getLocalName();
					addRows(connection, prefix, ROWS, (IRI) context);
					addSharedRows(connection, prefix, (IRI) context);
				}
				connection.commit();
				commits.incrementAndGet();
				reuse.minimumFree.accumulateAndGet(entries(store, "free_ids"), Math::min);
				try (RepositoryResult<Statement> rows = connection.getStatements(null, null, null, false, assigned)) {
					while (rows.hasNext()) {
						captureIds(rows.next().getObject(), reuse.componentIds, reuse.tripleIds);
					}
				}
				connection.begin(IsolationLevels.READ_COMMITTED);
				connection.clear(assigned);
				connection.commit();
				commits.incrementAndGet();
			}
		}
	}

	private static Seed seed(File directory) {
		SailRepository repository = new SailRepository(newStore(directory));
		repository.init();
		List<Statement> originals = new ArrayList<>();
		List<Statement> sharedOwners;
		Set<Long> releasedIds = new HashSet<>();
		Set<Long> releasedTripleIds = new HashSet<>();
		try (RepositoryConnection connection = repository.getConnection()) {
			connection.begin(IsolationLevels.READ_COMMITTED);
			for (int cohort = 0; cohort < CONTEXTS.length; cohort++) {
				originals.addAll(addRows(connection, "original-" + cohort, ROWS, CONTEXTS[cohort]));
				originals.addAll(addSharedRows(connection, "original-" + cohort, CONTEXTS[cohort]));
			}
			sharedOwners = addSharedRows(connection, "independent-shared-owner", SHARED_OWNER_CONTEXT);
			addRows(connection, "old-released", ROWS * 16, OLD_CONTEXT);
			connection.commit();
			try (RepositoryResult<Statement> old = connection.getStatements(null, null, null, false, OLD_CONTEXT)) {
				while (old.hasNext()) {
					captureIds(old.next().getObject(), releasedIds, releasedTripleIds);
				}
			}
			// Common predicates and datatypes are also used by live rows. Their unchanged IDs would not be
			// evidence of recycling, so remove every scalar ID with a surviving owner from the released set.
			Set<Long> survivingScalarIds = new HashSet<>();
			Resource[] survivingContexts = Arrays.copyOf(CONTEXTS, CONTEXTS.length + 1, Resource[].class);
			survivingContexts[CONTEXTS.length] = SHARED_OWNER_CONTEXT;
			try (RepositoryResult<Statement> surviving = connection.getStatements(null, null, null, false,
					survivingContexts)) {
				while (surviving.hasNext()) {
					captureIds(surviving.next().getObject(), survivingScalarIds, new HashSet<>());
				}
			}
			releasedIds.removeAll(survivingScalarIds);
			assertFalse(releasedIds.isEmpty(), "The recycling oracle must contain scalars with no surviving owner");
			connection.begin(IsolationLevels.READ_COMMITTED);
			connection.clear(OLD_CONTEXT);
			connection.commit();
			assertEquals(0, connection.size(OLD_CONTEXT));
		} finally {
			repository.shutDown();
		}
		return new Seed(originals, sharedOwners, releasedIds, releasedTripleIds);
	}

	private record Seed(List<Statement> statements, List<Statement> sharedOwners, Set<Long> releasedIds,
			Set<Long> releasedTripleIds) {
	}

	private static LmdbStore newStore(File directory) {
		return new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")
				.setTripleDBSize(128L * 1024 * 1024)
				.setValueDBSize(128L * 1024 * 1024)
				.setInlineLiterals(false)
				.setValueEvictionInterval(1)
				.setValueCacheSize(8)
				.setValueIDCacheSize(8)
				.setNamespaceCacheSize(8)
				.setNamespaceIDCacheSize(8));
	}

	private static List<Statement> addRows(RepositoryConnection connection, String prefix, int rows, IRI context) {
		List<Statement> statements = new ArrayList<>();
		for (int row = 0; row < rows; row++) {
			String key = prefix + ":" + row;
			Value value = nested(key, terminal(key, row), DEPTH);
			Statement statement = VF.createStatement(VF.createIRI("urn:row-subject:" + key), PREDICATE, value, context);
			connection.add(statement);
			statements.add(statement);
		}
		return statements;
	}

	private static List<Statement> addSharedRows(RepositoryConnection connection, String prefix, IRI context) {
		List<Statement> statements = new ArrayList<>();
		for (int row = 0; row < SHARED_ROWS; row++) {
			String sharedKey = "shared-inner:" + row;
			Value inner = nested(sharedKey, terminal(sharedKey, row), DEPTH - 2);
			String outerKey = prefix + ":shared-outer:" + row;
			Value outer = nested(outerKey, inner, 2);
			Statement statement = VF.createStatement(VF.createIRI("urn:row-subject:" + outerKey), PREDICATE,
					outer, context);
			connection.add(statement);
			statements.add(statement);
		}
		return statements;
	}

	private static Value terminal(String key, int variant) {
		return switch (variant % 4) {
		case 0 -> VF.createIRI("urn:unique-terminal:" + key);
		case 1 -> VF.createBNode("unique-terminal-" + key.replace(':', '-'));
		case 2 -> VF.createLiteral("unique lexical \u03bb\n" + key, VF.createIRI("urn:unique-datatype:" + key));
		default -> VF.createLiteral("unique language \u00e6 " + key, "nb");
		};
	}

	private static Value nested(String key, Value value, int layers) {
		for (int depth = 0; depth < layers; depth++) {
			Resource subject = depth % 2 == 0 ? VF.createIRI("urn:nested-subject:" + key + ":" + depth)
					: VF.createBNode("nested-subject-" + key.replace(':', '-') + "-" + depth);
			IRI predicate = VF.createIRI(depth % 2 == 0 ? "urn:shared-nested-predicate:" + depth
					: "urn:unique-nested-predicate:" + key + ":" + depth);
			value = VF.createTripleTerm(subject, predicate, value);
		}
		return value;
	}

	private static IRI context(String name) {
		return VF.createIRI("urn:buffered-terms:context:" + name);
	}

	private static long entries(LmdbStore store, String database) {
		return store.getLmdbStats().valueDatabases().get(database).entries();
	}

	private static void captureIds(Value value, Set<Long> components, Set<Long> triples) {
		if (value instanceof LmdbValue nativeValue && nativeValue.getInternalID() != LmdbValue.UNKNOWN_ID) {
			if (value instanceof TripleTerm) {
				triples.add(nativeValue.getInternalID());
			} else {
				components.add(nativeValue.getInternalID());
			}
		}
		if (value instanceof TripleTerm triple) {
			captureIds(triple.getSubject(), components, triples);
			captureIds(triple.getPredicate(), components, triples);
			captureIds(triple.getObject(), components, triples);
		} else if (value instanceof Literal literal) {
			captureIds(literal.getDatatype(), components, triples);
		}
	}

	private static boolean intersects(Set<Long> left, Set<Long> right) {
		return left.stream().anyMatch(right::contains);
	}

	private static long intersectionSize(Set<Long> left, Set<Long> right) {
		return left.stream().filter(right::contains).count();
	}

	private static List<Statement> expected(List<Statement> statements, int[] selection) {
		Set<Resource> contexts = new HashSet<>();
		for (int cohort : selection) {
			contexts.add(CONTEXTS[cohort]);
		}
		return statements.stream().filter(statement -> contexts.contains(statement.getContext())).toList();
	}

	private static void assertStatements(List<Statement> expected, List<Statement> actual) {
		assertEquals(expected.size(), actual.size(), "Buffered results must preserve exact row multiplicity");
		Map<String, Statement> bySubject = new LinkedHashMap<>();
		for (Statement statement : actual) {
			assertReady(statement.getSubject());
			assertReady(statement.getPredicate());
			assertReady(statement.getObject());
			assertReady(statement.getContext());
			assertEquals(null, bySubject.put(statement.getSubject().stringValue(), statement),
					"No duplicate rows may appear");
		}
		for (Statement statement : expected) {
			Statement retrieved = bySubject.get(statement.getSubject().stringValue());
			assertNotNull(retrieved, "Every original statement must survive deferred retrieval");
			assertCompleteValue(statement.getSubject(), retrieved.getSubject());
			assertCompleteValue(statement.getPredicate(), retrieved.getPredicate());
			assertCompleteValue(statement.getObject(), retrieved.getObject());
			assertCompleteValue(statement.getContext(), retrieved.getContext());
			assertEquals(statement, retrieved);
		}
	}

	private static void assertCompleteValue(Value expected, Value actual) {
		if (expected instanceof TripleTerm expectedTerm) {
			TripleTerm term = assertInstanceOf(TripleTerm.class, actual);
			assertCompleteValue(expectedTerm.getSubject(), term.getSubject());
			assertCompleteValue(expectedTerm.getPredicate(), term.getPredicate());
			assertCompleteValue(expectedTerm.getObject(), term.getObject());
		} else if (expected instanceof Literal expectedLiteral) {
			Literal literal = assertInstanceOf(Literal.class, actual);
			assertEquals(expectedLiteral.getLabel(), literal.getLabel());
			assertEquals(expectedLiteral.getLanguage(), literal.getLanguage());
			assertEquals(expectedLiteral.getDatatype().stringValue(), literal.getDatatype().stringValue());
		} else if (expected instanceof BNode expectedBNode) {
			assertEquals(expectedBNode.getID(), assertInstanceOf(BNode.class, actual).getID());
		} else {
			assertInstanceOf(IRI.class, actual);
			assertEquals(expected.stringValue(), actual.stringValue());
		}
		assertEquals(expected, actual);
	}

	private static void assertReady(Value value) {
		if (value instanceof LmdbValue nativeValue) {
			assertTrue(nativeValue.isInitialized(), "Repository results must arrive recursively materialized");
		}
		if (value instanceof TripleTerm triple) {
			assertReady(triple.getSubject());
			assertReady(triple.getPredicate());
			assertReady(triple.getObject());
		} else if (value instanceof Literal literal) {
			assertReady(literal.getDatatype());
		}
	}

	private static LmdbValue assertUnresolved(Value value) {
		LmdbValue nativeValue = assertInstanceOf(LmdbValue.class, value);
		assertFalse(nativeValue.isInitialized(), "The wrapper must hold ID-only values without lexical resolution");
		return nativeValue;
	}

	private static void await(CountDownLatch latch, String message) {
		try {
			assertTrue(latch.await(30, TimeUnit.SECONDS), message);
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new SailException(message, failure);
		}
	}

	private static final class ReuseEvidence {
		private final AtomicLong minimumFree;
		private final Set<Long> componentIds = ConcurrentHashMap.newKeySet();
		private final Set<Long> tripleIds = ConcurrentHashMap.newKeySet();

		private ReuseEvidence(long initialFree) {
			minimumFree = new AtomicLong(initialFree);
		}
	}

	private static final class BufferGate {
		private final int rowCount;
		private final SourceLifetime lifetime;
		private final CountDownLatch buffered;
		private final CountDownLatch release;
		private final List<Value> roots = new ArrayList<>();
		private volatile Throwable failure;
		private volatile boolean sourceClosed;

		private BufferGate(int rowCount, SourceLifetime lifetime, CountDownLatch buffered, CountDownLatch release) {
			this.rowCount = rowCount;
			this.lifetime = lifetime;
			this.buffered = buffered;
			this.release = release;
		}

		private void record(Value value) {
			LmdbBufferedTripleTermTest.assertUnresolved(value);
			roots.add(value);
		}

		private void assertUnresolved() {
			assertEquals(rowCount, roots.size(), "The buffer must contain every raw nested value root");
			roots.forEach(LmdbBufferedTripleTermTest::assertUnresolved);
		}
	}

	/** Ordinary wrappers retain their exposure forwarding; the buffer itself never invokes a value getter. */
	private static final class BufferingSail extends NotifyingSailWrapper {
		private final ThreadLocal<BufferGate> gate = new ThreadLocal<>();

		private BufferingSail(LmdbStore store) {
			super(store);
		}

		@Override
		public NotifyingSailConnection getConnection() {
			return new NotifyingSailConnectionWrapper(new NotifyingSailConnectionWrapper(super.getConnection()) {
				@Override
				public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate,
						Value object,
						boolean includeInferred, Resource... contexts) {
					CloseableIteration<? extends Statement> source = super.getStatements(subject, predicate, object,
							includeInferred, contexts);
					return buffer(source, SailResultValueExtractor.STATEMENTS, row -> {
						gate.get().record(row.getObject());
					});
				}

				@Override
				public CloseableIteration<? extends BindingSet> evaluate(TupleExpr expression, Dataset dataset,
						BindingSet bindings, boolean includeInferred) {
					return buffer(super.evaluate(expression, dataset, bindings, includeInferred),
							SailResultValueExtractor.BINDING_SETS, row -> {
								gate.get().record(row.getValue("o"));
							});
				}
			}) {
			};
		}

		private <T> CloseableIteration<? extends T> buffer(CloseableIteration<? extends T> source,
				SailResultValueExtractor<T> extractor, Consumer<T> recorder) {
			BufferGate current = gate.get();
			if (current == null) {
				return source;
			}
			List<T> rows = new ArrayList<>();
			try {
				for (int row = 0; row < current.rowCount; row++) {
					assertTrue(source.hasNext(), "The raw reader must contain its entire expected cohort");
					T value = extractor.snapshot(source.next());
					recorder.accept(value);
					rows.add(value);
				}
				if (current.lifetime == SourceLifetime.EXHAUSTED_AND_CLOSED) {
					assertFalse(source.hasNext(), "The source must be completely exhausted before repository exposure");
					source.close();
					current.sourceClosed = true;
				}
				current.assertUnresolved();
			} catch (Throwable failure) {
				current.failure = failure;
				source.close();
				current.sourceClosed = true;
				throw failure;
			} finally {
				current.buffered.countDown();
			}
			try {
				await(current.release, "Repository value preparation must wait for every writer commit");
			} catch (Throwable failure) {
				source.close();
				current.sourceClosed = true;
				throw failure;
			}
			return new CloseableIteratorIteration<>(rows.iterator()) {
				@Override
				protected void handleClose() {
					try {
						super.handleClose();
					} finally {
						source.close();
						current.sourceClosed = true;
					}
				}
			};
		}
	}
}
